import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

const val MOD: Long = 998244353
const val MAX_N: Int = 2 * 100000 + 1

fun modPow(base: Long, exp: Long, mod: Long): Long {
    var b = base % mod
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) res = (res * b) % mod
        b = (b * b) % mod
        e = e shr 1
    }
    return res
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val fac = LongArray(MAX_N + 1)
    val facInv = LongArray(MAX_N + 1)

    fac[0] = 1L
    for (i in 1..MAX_N) {
        fac[i] = fac[i - 1] * i % MOD
    }

    facInv[MAX_N] = modPow(fac[MAX_N], MOD - 2, MOD)
    for (i in MAX_N downTo 1) {
        facInv[i - 1] = facInv[i] * i % MOD
    }

    fun modNCr(nn: Int, rr: Int): Long {
        if (nn < rr || nn < 0 || rr < 0) return 0L
        val tmp = facInv[nn - rr] * facInv[rr] % MOD
        return tmp * fac[nn] % MOD
    }

    var ans: Long
    if (n - 3 > 0) {
        ans = modNCr(m, n - 1) * (n - 2).toLong() % MOD
        ans = ans * modPow(2L, (n - 3).toLong(), MOD) % MOD
    } else {
        ans = modNCr(m, n - 1) * (n - 2).toLong() % MOD
    }
    ans %= MOD
    println(ans)
}

